data class User(val name: String, val age: Int)

fun greet(user: User) = "Hello, " + user.name + "!"

fun main() {
    val users = listOf(User("Alice", 30), User("Bob", 25))
    users.filter { it.age > 26 }.forEach { println(greet(it)) }
}
